#include <iostream>
#include <vector>

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    std::vector<int> v;
    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
    }

    int q{};
    std::cin >> q;
    for (int i = 0; i < q; ++i)
    {
        int target{};
        std::cin >> target;

        int less{};
        int equal{};
        int greater{};
        for (int x : v)
        {
            if (x < target)      ++less;
            else if (x == target) ++equal;
            else                  ++greater;
        }

        std::cout << target << " less " << less
                  << " equal " << equal
                  << " greater " << greater << "\n";
    }

    return 0;
}

