import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    n = int(data[pos]); pos += 1
    v = [int(data[pos + i]) for i in range(n)]; pos += n
    q = int(data[pos]); pos += 1
    out = []
    for _ in range(q):
        target = int(data[pos]); pos += 1
        less = equal = greater = 0
        for x in v:
            if x < target:
                less += 1
            elif x == target:
                equal += 1
            else:
                greater += 1
        out.append("%d less %d equal %d greater %d" % (target, less, equal, greater))
    print("\n".join(out))

main()
